import{_ as a,o as r,c as o,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"键盘、手柄与键位","description":"","frontmatter":{},"headers":[],"relativePath":"use/input.md","filePath":"use/input.md","lastUpdated":1791133906000}'),s={name:"use/input.md"};function d(l,t,i,n,p,h){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="键盘、手柄与键位" tabindex="-1">键盘、手柄与键位 <a class="header-anchor" href="#键盘、手柄与键位" aria-label="Permalink to &quot;键盘、手柄与键位&quot;">​</a></h1><p>本篇说明框架界面的输入方式，以及为什么某些设计是现在这样。</p><h2 id="框架界面怎么操作" tabindex="-1">框架界面怎么操作 <a class="header-anchor" href="#框架界面怎么操作" aria-label="Permalink to &quot;框架界面怎么操作&quot;">​</a></h2><p>控制台「小u」是<strong>纯触摸操作</strong>的：</p><table tabindex="0"><thead><tr><th>操作</th><th>手势</th></tr></thead><tbody><tr><td>打开面板</td><td>轻点悬浮窗</td></tr><tr><td>强制打开</td><td><strong>三指同按屏幕</strong></td></tr><tr><td>移动悬浮窗</td><td>按住拖动</td></tr><tr><td>移动面板</td><td>拖动标题栏</td></tr><tr><td>收起面板</td><td>点面板外的灰色区域</td></tr><tr><td>切页</td><td>点顶部标签</td></tr><tr><td>调参数</td><td>拖滑块</td></tr><tr><td>滚动</td><td>上下滑动</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">没有键盘操作</p><p>框架的界面<strong>完全为触摸设计</strong>，不需要键盘或手柄。</p><p>悬浮窗的位置也可以拖到任何地方，适应你的握持习惯。</p></div><h2 id="点击判定的设计" tabindex="-1">点击判定的设计 <a class="header-anchor" href="#点击判定的设计" aria-label="Permalink to &quot;点击判定的设计&quot;">​</a></h2><p>框架对触摸判定做了特殊处理，值得说明：</p><h3 id="判定区比视觉大" tabindex="-1">判定区比视觉大 <a class="header-anchor" href="#判定区比视觉大" aria-label="Permalink to &quot;判定区比视觉大&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>视觉</th><th>判定</th></tr></thead><tbody><tr><td>悬浮窗</td><td>34 px</td><td><strong>54 px</strong></td></tr><tr><td>主按钮</td><td>高 30 px</td><td><strong>高 46 px</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么</p><p>手机上手指的接触面积比鼠标大得多。</p><p>如果判定区 = 视觉范围，玩家会觉得「明明点到了却没反应」。</p><p><strong>视觉上可以小（好看），但判定必须大（好点）。</strong></p></div><p>注意：<strong>左右方向不外扩</strong> —— 否则相邻按钮会抢点击，反而更容易点错。</p><h3 id="位移阈值按屏幕比例" tabindex="-1">位移阈值按屏幕比例 <a class="header-anchor" href="#位移阈值按屏幕比例" aria-label="Permalink to &quot;位移阈值按屏幕比例&quot;">​</a></h3><p>判断「点击」还是「拖动」的阈值，用的是<strong>屏幕宽度的百分比</strong>，不是固定像素。</p><div class="warning custom-block"><p class="custom-block-title">为什么不用固定值</p><p>手机上手指按下必然有轻微抖动。</p><p>如果阈值是固定的 6 像素，<strong>几乎每次点按都会被判成拖动</strong> —— 结果就是面板永远打不开。</p><p>所以要按 <code>屏宽 × 2%</code>（最小 12 px）来算。</p></div><h3 id="为「收不到事件」做的兜底" tabindex="-1">为「收不到事件」做的兜底 <a class="header-anchor" href="#为「收不到事件」做的兜底" aria-label="Permalink to &quot;为「收不到事件」做的兜底&quot;">​</a></h3><p>部分安卓设备在抬手时收不到界面点击事件。</p><p>框架为此做了三重保险：</p><ol><li><strong>点击超时兜底</strong> —— 按下后一段时间没检测到移动，按「点击」处理</li><li><strong>位移阈值按比例</strong> —— 减少抖动误判</li><li><strong>三指手势</strong> —— 完全不依赖点击事件</li></ol><h2 id="游戏本身的输入" tabindex="-1">游戏本身的输入 <a class="header-anchor" href="#游戏本身的输入" aria-label="Permalink to &quot;游戏本身的输入&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">框架不改变游戏的输入方式</p><p>游戏的<strong>战斗操作</strong>（选择目标、发射、机动）仍然是原来的方式，框架没有改动它。</p><p>框架的界面是<strong>独立的一层</strong>，浮在游戏之上。</p></div><h3 id="一个重要的注意事项" tabindex="-1">一个重要的注意事项 <a class="header-anchor" href="#一个重要的注意事项" aria-label="Permalink to &quot;一个重要的注意事项&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">别把悬浮窗放在战斗按钮上</p><p>框架的界面层虽然独立，但<strong>视觉上会遮挡</strong>下面的按钮。</p><p>如果你的悬浮窗压在射击按钮上，点射击时会点到悬浮窗。</p><p><strong>所以：悬浮窗默认位置在屏幕上方，也建议你保持在那附近。</strong></p></div><h2 id="关于「两套输入管线」" tabindex="-1">关于「两套输入管线」 <a class="header-anchor" href="#关于「两套输入管线」" aria-label="Permalink to &quot;关于「两套输入管线」&quot;">​</a></h2><p>技术上有件事值得说明，因为它影响排查思路：</p><table tabindex="0"><thead><tr><th>系统</th><th>用途</th><th>输入方式</th></tr></thead><tbody><tr><td><strong>NGUI</strong>（游戏自带）</td><td>战斗界面、菜单</td><td>轮询输入状态</td></tr><tr><td><strong>OnGUI</strong>（框架使用）</td><td>控制台面板</td><td>事件驱动</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这意味着什么</p><p>框架的界面和游戏的界面<strong>是两套独立的输入系统</strong>。</p><p>这带来一个好处：框架的界面<strong>不会拦截游戏按钮的点击</strong>（它们走不同的通道）。</p><p>但也带来一个注意点：<strong>如果视觉上重叠，玩家会点到上层的东西</strong>。</p><p>所以位置选择很重要。</p></div><h2 id="常见输入问题" tabindex="-1">常见输入问题 <a class="header-anchor" href="#常见输入问题" aria-label="Permalink to &quot;常见输入问题&quot;">​</a></h2><h3 id="悬浮窗点不动" tabindex="-1">悬浮窗点不动 <a class="header-anchor" href="#悬浮窗点不动" aria-label="Permalink to &quot;悬浮窗点不动&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">第一招：三指同按</p><p><strong>三根手指同时按屏幕</strong> —— 这是强制唤起，绕过所有点击判定。</p></div><p>如果还不行：</p><ol><li>看看是不是被别的东西挡住了</li><li>试试删掉 <code>AFMOD_settings.json</code>（重置位置）</li><li>检查游戏其他界面是否也点不动（如果是，不是框架的问题）</li></ol><h3 id="面板里的按钮点不准" tabindex="-1">面板里的按钮点不准 <a class="header-anchor" href="#面板里的按钮点不准" aria-label="Permalink to &quot;面板里的按钮点不准&quot;">​</a></h3><p>框架已经做了判定区外扩。如果还是不好点：</p><ul><li>放大手指接触面积（用指腹而不是指尖）</li><li>或者拖动面板到更舒服的位置</li></ul><h3 id="滑块拖不动-跳来跳去" tabindex="-1">滑块拖不动 / 跳来跳去 <a class="header-anchor" href="#滑块拖不动-跳来跳去" aria-label="Permalink to &quot;滑块拖不动 / 跳来跳去&quot;">​</a></h3><p>可能是手指滑动的方向不完全是水平。试着<strong>更水平地拖动</strong>。</p><p>如果还是不行，某些参数可以用<strong>一键预设按钮</strong>代替拖滑块。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>操作技巧详解 → <a href="/AtlanticFleetSite/docs/use/gestures">悬浮窗操作技巧</a></li><li>面板总览 → <a href="/AtlanticFleetSite/docs/use/panel">游戏内控制台「小u」</a></li><li>点不动排查 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li></ul>',40)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
